    ('backend/app/backtest/replay/replay_core.py', '                       "hidden_sessions": hidden},', '                       "hidden_sessions": hidden,\n                       "frame_from_ts": spec.get("frame_from_ts")},   # ── EMC_V1_FIX1_20261011 ── "Trade" framing starts here when earlier than the entry', 1),
    ('frontend/src/components/replay/TradeReplay.jsx', '  const ue = uIn(ds, d?.group?.entry_ts) ?? 0;\n  const ux = uIn(ds, d?.group?.exit_ts ?? d?.group?.entry_ts) ?? ue;\n  const pad = Math.max(45, (ux - ue) * 0.25);', '  const ue0 = uIn(ds, d?.group?.entry_ts) ?? 0;\n  const uf = uIn(ds, d?.window?.frame_from_ts);   // ── EMC_V1_FIX1_20261011 ── e.g. the arming signal before the entry\n  const ue = uf != null && uf < ue0 ? uf : ue0;\n  const ux = uIn(ds, d?.group?.exit_ts ?? d?.group?.entry_ts) ?? ue0;\n  const pad = Math.max(45, (ux - ue) * 0.25);', 1),
